------------------------------------------------- private

function UIActivityAccumulatedRechargeCellNode:RefreshData_()
    local cellData = self:GetCellData()
    local statusId = checkInt(cellData.status)
    local isUndone = statusId == Constants.GetStatus.Not
    local isCanGet = statusId == Constants.GetStatus.Can
    local isHasGot = statusId == Constants.GetStatus.Has

    -- update heads
    KTool.SetActive(self.FloorNormal, isUndone)
    KTool.SetActive(self.FloorFinish, not isUndone)
    if not isUndone then
        CfUtils.SetUISwitchImage(self.ImgFrame, isCanGet and 1 or 2)
        CfUtils.SetUISwitchImage(self.ImgFrame2, isCanGet and 1 or 2)
    end

    -- update amountNum
    local leftAmount = checkInt(cellData.amount) - self:GetPayAmount()
    CfUtils.FillText(self.TxtNumber, tostring(leftAmount))

    -- update goodsList
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    self.CommonGoodsList.Env:FreshBaseUI(cellData.rewards, false, isHasGot)
    --self.CommonGoodsList.Env:SetCanGetEffectShow(isCanGet)

    -- update footer
    KTool.SetActive(self.Black, isHasGot)
    KTool.SetActive(self.ImgFinish, isHasGot)
    KTool.SetActive(self.FontStyleButton, not isHasGot)
    KTool.SetActive(self.CanAnim, isCanGet)
    if not isHasGot then
        if isCanGet then
            self.FontStyleButton:ResetFontStyle("B23", localize("领取"))
        else
            self.FontStyleButton:ResetFontStyle("B24", localize("前往"))
        end
    end
end


function UIActivityAccumulatedRechargeCellNode:OnClickFunctionButtonHandler_()
    if self:GetClickCB() then
        self:GetClickCB()(self:GetLuaIndex())
    end
end


return UIActivityAccumulatedRechargeCellNode
